import {enhanceScreens,applyClusterFilter} from './screens.js';
import {icon} from './icons.js';
import {draw3} from './view3d.js';
import {definitions} from './definitions.js';
import * as C from './core.js';
import {sample} from './data.js';
const $=id=>document.getElementById(id), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=x=>x==null?'Not defined':Number(x).toLocaleString('en',{maximumFractionDigits:3});
const colors=['#287b6c','#b66532','#6663ad','#bc4773','#4279b2','#858128','#963f3e','#466d31','#835a91','#226a80','#905e29','#575f69'];
const stages=['Data','Features','Train','Explore','Model Card'],intros=['Use a sample or upload your own table. Then choose the features to group by.','Choose which numerical features should influence similarity.','Choose how many groups the model should form. The model will learn the centers of those groups.','Investigate what the groups have in common and how your choices affect the results.','Explain what you built, the evidence behind your choices, and the model’s limitations.'];
const fresh=()=>({schema:1,kind:'cluster-lab-project',stage:0,data:sample(),features:[1,2,3,4],display:0,scale:true,missing:'drop',k:3,seed:42,restarts:10,maxIter:300,notes:{},runs:[],active:null,stale:false,view:'features',axes:[0,1],tab:'results',tsne:{perplexity:20,iterations:500,learningRate:10,seed:42},comparison:[0,1],dimensions:2,axisZ:2,camera:{yaw:35,pitch:20,zoom:1}});
let inspectedModel=null, selectedPoint=null, searchText="", expanded=false;
let S=fresh(),step=null,timer=null,worker=null,busy=false,saveTimer=null;
const signature=()=>JSON.stringify([S.data,S.features,S.scale,S.missing,S.k,S.seed,S.restarts,S.maxIter]);
function status(t){$('save-status').textContent=t;}
function notice(t='',kind='warning'){ $('notice').textContent=t; $('notice').dataset.kind=kind; }
function persist(){try{localStorage.setItem('cluster-lab-v1',JSON.stringify(S));status('Saved in this browser');}catch(e){status('Autosave unavailable · download a backup');}}
function saveSoon(){status('Saving…');clearTimeout(saveTimer);saveTimer=setTimeout(persist,200);}
function field(key,label,hint='',value=null){const content=`<label class="field"><span>${esc(label)}</span><textarea data-note="${key}" ${busy?'disabled':''}>${esc(value??S.notes[key]??'')}</textarea>${hint?`<small>${esc(hint)}</small>`:''}</label>`;return S.stage===4?content:`<details class="optional-note"><summary>Optional notes: ${esc(label)}</summary>${content}</details>`;}

function select(id,label,options,value){return `<label class="field"><span>${label}${labelHelp(label)}</span><select id="${id}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;}
function num(id,label,value,min,max){return `<label class="field"><span>${label}${labelHelp(label)}</span><input id="${id}" type="number" value="${value}" min="${min}" max="${max}" step="1"></label>`;}
function button(id,label,primary=false,disabled=false){return `<button id="${id}" class="${primary?'primary':''}" ${disabled?'disabled':''}>${label}</button>`;}
function table(headers,rows,limit=500){return `<div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,limit).map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function prepared(){return C.prepare(S.data,S.features,S.scale,S.missing);}
function available(){return S.active&&!S.stale;}
function invalidate(){cancelWork();step=null;S.stale=!!S.active;saveSoon();}
function cancelWork(){if(worker)worker.terminate();worker=null;busy=false;if(timer)clearInterval(timer);timer=null;}
function next(){return `<div class="next">${S.stage?button('back','← Back'): '<span class="fine">No correct categories required.</span>'}${S.stage<4?button('next',`Continue to ${stages[S.stage+1]} →`,true):''}</div>`;}
function units(j,data=S.data){return data.units?.[j]||'units not supplied';}
function plot(points,labels=[],centers=[],axis=['Horizontal','Vertical'],names=[]){if(!points?.length)return '<div class="empty">Train a model to reveal its groups.</div>';let all=[...points,...centers],mins=[0,1].map(j=>Math.min(...all.map(r=>r[j]))),maxs=[0,1].map(j=>Math.max(...all.map(r=>r[j]))),padding=mins.map((v,j)=>(maxs[j]-v||Math.max(Math.abs(v),1))*.08);mins=mins.map((v,j)=>v-padding[j]);maxs=maxs.map((v,j)=>v+padding[j]);let pos=(x,j)=>{let t=(x-mins[j])/(maxs[j]-mins[j]||1);return j?340-t*290:60+t*610;};let ticks='';for(let i=0;i<=4;i++){let t=i/4;ticks+=`<line x1="60" x2="670" y1="${340-t*290}" y2="${340-t*290}" stroke="#e4ece7"/><text x="49" y="${344-t*290}" font-size="11" text-anchor="end" fill="#536771">${fmt(mins[1]+t*(maxs[1]-mins[1]))}</text><text x="${60+t*610}" y="362" font-size="11" text-anchor="middle" fill="#536771">${fmt(mins[0]+t*(maxs[0]-mins[0]))}</text>`;}
 return `<svg class="plot" viewBox="0 0 720 410" role="img" aria-label="Scatterplot of ${points.length} examples. Numbered centers and a data table identify clusters."><rect x="60" y="50" width="610" height="290" rx="7" fill="#f8fbf9"/>${ticks}${points.map((x,i)=>`<circle cx="${pos(x[0],0)}" cy="${pos(x[1],1)}" r="4.5" fill="${labels.length?colors[labels[i]%12]:'#8aaba0'}" opacity=".78"><title>${esc(names[i]||`Example ${i+1}`)}${labels.length?` · Cluster ${labels[i]+1}`:''}</title></circle>`).join('')}${centers.map((c,i)=>`<g><rect x="${pos(c[0],0)-12}" y="${pos(c[1],1)-12}" width="24" height="24" rx="4" fill="${colors[i]}" stroke="white" stroke-width="2"/><text x="${pos(c[0],0)}" y="${pos(c[1],1)+4}" text-anchor="middle" fill="white" font-weight="700" font-size="12">${i+1}</text></g>`).join('')}<text x="365" y="397" text-anchor="middle" font-size="12" fill="#334f45">${esc(axis[0])}</text><text x="16" y="195" transform="rotate(-90 16 195)" text-anchor="middle" font-size="12" fill="#334f45">${esc(axis[1])}</text></svg>`;
}
function render(){
 $('steps').innerHTML=stages.map((s,i)=>`<button data-stage="${i}" ${i===S.stage?'aria-current="step"':''} ${busy?'disabled':''}><span class="stepnum">${i+1}</span>${icon(['data','features','train','explore','card'][i])}<span>${s}</span></button>`).join('');
 $('main').innerHTML=`<div class="eyebrow">LEARN BY EXPLORING · Step ${S.stage+1} of 5</div><h1>${['Choose your data.','Choose your features.','Train your model.','Explore your groups.','Describe your model.'][S.stage]}</h1><p class="intro">${intros[S.stage]}</p>${S.stale?'<div class="callout warning">Settings changed. Your previous model is outdated. Train again before applying or exporting it. Saved runs are preserved.</div>':''}${S.stage===2?'<div class="learning-strip" aria-label="K-means learning sequence"><span><b>1</b> Place initial centers</span><span><b>2</b> Assign nearest examples</span><span><b>3</b> Move centers to means</span><span><b>4</b> Repeat until stable</span></div>':S.stage===0?'<p class="context-tip"><strong>Unsupervised learning:</strong> Choose a dataset, train a clustering model, and explore the results—no coding or correct category labels needed.</p>':''}${[dataPage,featurePage,trainPage,explorePage,cardPage][S.stage]()}${next()}`;
 enhanceScreens($('main'),S,step,{esc,fmt,plot,select,table,help,notice,upload:importCSV,choose:i=>{selectedPoint=i;render();$('point-choice')?.focus();}});bind();
}
function dataPage(){const desc=C.describe(S.data),missing=desc.reduce((a,d)=>a+d.missing,0);return `<div class="start-options"><section class="panel"><span class="eyebrow">READY-MADE DATA</span><h2 class="icon-heading">${icon('data')}Try a sample</h2><p class="hint">Explore Singapore air quality, wildlife, or vehicles—or start with a synthetic music sample.</p>${select('sample','Sample dataset',['air','penguins','cars','songs','objects','separated','overlapping','continuous','curved'].map(k=>[k,sample(k).name]),['air','penguins','cars','songs','objects','separated','overlapping','continuous','curved'].find(k=>sample(k).name===S.data.name)||'songs')}${button('load-sample','Load sample data')}</section><section class="panel"><span class="eyebrow">YOUR OWN DATA</span><h2 class="icon-heading">${icon('upload')}Upload a CSV</h2><p class="hint">Use a table with at least two numerical features.</p>${button('upload-csv','Upload CSV')}<details><summary>CSV requirements</summary><p>Up to 500 examples, 25 columns, 2 MB. Use unique column names in the first row. Blank cells represent missing values. No categories are needed.</p></details></section></div><section class="panel data-preview" tabindex="-1" aria-label="Active dataset preview"><div class="sectionbar"><div><span class="eyebrow">CURRENT DATASET</span><h2>${esc(S.data.name)}</h2></div><span class="badge">${S.data.rows.length} examples · ${desc.filter(d=>d.numeric&&!d.reserved).length} numerical features</span></div><p class="fine">Preview of the first ${Math.min(5,S.data.rows.length)} rows.${S.data.source?.includes('synthetic')?' Synthetic data for exploration.':''}</p>${S.data.context?`<p>${esc(S.data.context)}</p>`:''}${table(S.data.headers,S.data.rows,5)}${missing?`<p class="callout warning">${missing} missing values. Choose how to handle them in Features.</p>`:''}<details><summary>View all data and column details</summary><p>${esc(S.data.description)}</p><p class="fine">Source: ${esc(S.data.source)}</p>${table(S.data.headers,S.data.rows)}${table(['Column','Type','Range','Missing'],desc.map(d=>[d.name,d.numeric?'Numerical':'Text',d.numeric?`${fmt(d.min)} – ${fmt(d.max)}`:'—',d.missing]))}${select('display','Display-name column',[[-1,'Row number (no display column)'],...S.data.headers.map((h,i)=>[i,h])],S.display)}<p class="fine">Display names remain metadata, never model inputs.</p>${button('sample-csv','Download this dataset')}</details><details><summary>Optional project notes</summary><p class="fine">You can complete reflections in a separate document. Notes here are optional.</p>${field('purpose','What are you grouping, and why?')}${field('source','Data source and limitations')}</details></section>`;}

function featurePage(){let prep=null,error='';try{prep=prepared();}catch(e){error=e.message;}return `<div class="layout"><section class="panel"><h2>Features used for grouping</h2><p class="hint">Select at least two numerical features. Uncheck features that should not influence similarity.</p><fieldset><legend class="fine">Available columns</legend>${C.describe(S.data).map((d,i)=>`<label class="check"><input type="checkbox" data-feature="${i}" ${S.features.includes(i)?'checked':''} ${!d.numeric||d.reserved||d.constant||i===S.display?'disabled':''}><span><strong>${esc(d.name)}</strong><small>${!d.numeric?'Text · metadata only':d.reserved||i===S.display?'Identifier or category · metadata only':d.constant?'Constant · no variation to group by':`${fmt(d.min)}–${fmt(d.max)} ${esc(units(i))} · ${d.missing} missing`}</small></span></label>`).join('')}</fieldset></section><aside class="panel side"><span class="eyebrow">02 / PREPARE</span><h2>Make a fair comparison</h2><label class="check"><input id="scale" type="checkbox" ${S.scale?'checked':''}><span><strong>Standardize feature scales</strong> ${help('Standardization')}<small>Gives each feature a comparable scale so larger numbers do not automatically dominate distance.</small></span></label>${select('missing','Missing numerical values',[['drop','Remove incomplete rows'],['mean','Fill with feature mean']],S.missing)}<div class="callout ${error?'warning':''}">${esc(error)||`${prep.X.length} examples ready. ${prep.removed} rows removed; ${prep.filled} values filled.${prep.prep.excluded.length?' Constant columns excluded: '+esc(prep.prep.excluded.join(', ')):''}`}</div>${field('features','Why should these features influence similarity?','We selected these features because…')}<details><summary>How standardization works</summary><p>For each feature: z = (value − mean) ÷ population standard deviation. The model saves these values and reuses them for new examples. Constant features are excluded.</p></details></aside></div>`;}
function trainPage(){let p,error='';try{p=prepared();C.createStepper(p.X,S.k,S.seed,null,S.maxIter);}catch(e){error=e.message;}
 let st=step,active=available()?S.active:null,X=st?.X||active?.X||p?.X;let labels=st?(st.labels||[]):(active?.model.labels||[]),centers=st?st.centers:(active?.model.centers||[]);return `<div class="layout"><section class="panel"><div class="sectionbar"><h2>${st?'Watch one learning run':'Clustering workspace'}</h2><span class="badge">${busy?'Calculating…':st?({initial:'1 · Initial centers',assign:'2 · Nearest-center assignment',update:st.done?'Run complete':'3 · Centers moved to means'}[st.phase]):active?'Model fitted':'Ready to discover'}</span></div>${plot(X?.map(r=>r.slice(0,2)),labels,centers.map(r=>r.slice(0,2)),[`${p?.prep.names[0]||'Feature 1'} (${S.scale?'standardized':'original units'})`,`${p?.prep.names[1]||'Feature 2'} (${S.scale?'standardized':'original units'})`])}<p class="fine">First two fitted features shown. All selected features influence distance. Numbered squares are centers (centroids). ${help('Centroid')}</p><div class="toolbar">${button('watch','Watch step by step',false,!!error||busy)}${button('step','Next learning step',false,!st||st.done||busy)}${button('play',timer?'Pause':'Run',false,!st||st.done||busy)}${button('reset','Reset learning',false,!st||busy)}</div>${st?`<p class="hint">${st.phase==='assign'?'Each example has been assigned to its nearest current center. The next step recalculates the means.':st.phase==='update'?'Each center is now the mean of its assigned examples.':'Centers are initialized with K-means++. No categories are supplied.'} Updates: ${st.iteration}. ${st.done?(st.converged?'Assignments and centers agree: converged.':'Iteration limit reached: not converged.') : ''}</p>`:''}${active?`<div class="callout">${active.model.converged?'Converged':'Iteration limit reached — not converged'} after ${active.model.iterations} center updates. ${active.settings.restarts} initialization${active.settings.restarts===1?'':'s'} used. Inertia: ${fmt(active.model.inertia)}.</div>`:''}${busy?'<p role="status">Fitting in a background worker…</p>'+button('cancel','Cancel training'):''}</section><aside class="panel side"><span class="eyebrow">03 / TRAIN</span><h2>Set the number of groups</h2>${num('k','Number of clusters (K)',S.k,1,12)}<p class="fine">K is your choice. The model learns the centers and assigns examples to them.</p>${error?`<div class="callout warning">${esc(error)}</div>`:''}${button('fit','Train clustering model',true,!!error||busy)}<details><summary>Advanced settings</summary>${num('seed','Random seed',S.seed,0,2147483647)}${num('restarts','Initializations',S.restarts,1,20)}${num('maxIter','Maximum center updates',S.maxIter,1,1000)}<p>Ordinary fitting keeps the lowest-inertia converged run. Step mode uses one initialization. Equal distances choose the first center.</p></details>${field('learned','What did you choose, and what did the model learn?')}${field('prediction','Before your next run: what do you predict will change?','Change one factor at a time; keep other settings fixed.')}<details><summary>How K-means learns</summary><p>1. Initialize centers.<br>2. Assign each example to its nearest center using squared Euclidean distance.<br>3. Replace each center with the mean of its assigned points.<br>4. Repeat until assignments agree.</p><p>Distance² = Σ(feature − center)². This process can reach different local solutions.</p></details></aside></div>`;}
function plotData(a){const dimensions=S.dimensions||2;let axis,points,centers;if(S.view==='pca'){const key='pca'+dimensions,p=a[key]||(a[key]=C.pca(a.X,dimensions));points=p.points;centers=C.projectPCA(a.model.centers,p);axis=p.variance.map((v,i)=>`PC${i+1} · ${(v*100).toFixed(1)}% variance`);}else if(S.view==='tsne'){points=(dimensions===3?a.embedding3:a.embedding)?.points;centers=[];axis=Array.from({length:dimensions},(_,i)=>`t-SNE ${i+1} · no original units`);}else{let axes=[...S.axes,...(dimensions===3?[S.axisZ??2]:[])].map(i=>Math.min(i,a.prep.names.length-1));points=a.raw.map(r=>axes.map(i=>r[i]));centers=a.model.centers.map(r=>axes.map(i=>a.prep.scale?r[i]*a.prep.stds[i]+a.prep.means[i]:r[i]));axis=axes.map(i=>`${a.prep.names[i]} (${units(a.prep.features[i],a.data)})`);}return {points,centers,axis,names:a.indices.map(i=>a.display<0?`Row ${i+1}`:a.data.rows[i][a.display])};}
function neighbors(a){return selectedPoint==null?[]:a.X.map((x,i)=>({i,d:C.d2(x,a.X[selectedPoint])})).filter(r=>r.i!==selectedPoint).sort((a,b)=>a.d-b.d||a.i-b.i).slice(0,5);}
function modelPlot(a){if(inspectedModel!==a){inspectedModel=a;selectedPoint=null;searchText='';}if(S.dimensions===3&&S.view!=='tsne'&&Math.min(a.X.length,a.prep.names.length)<3)return '<div class="callout">Select at least three usable features (and three examples for PCA) for a 3D view, or switch to 2D.</div>';const p=plotData(a);if(!p.points)return '<div class="empty">Compute t-SNE to create this dimensional view.</div>';return S.dimensions===3?draw3(p.points,a.model.labels,p.centers,p.axis,p.names,S.camera||{yaw:35,pitch:20,zoom:1},colors,esc,fmt,{selected:selectedPoint,neighbors:neighbors(a).map(r=>r.i)}):plot(p.points,a.model.labels,p.centers,p.axis,p.names);}
function help(term){return `<button type="button" class="help-button" data-help="${esc(term)}" aria-label="Define ${esc(term)}" aria-haspopup="dialog">?</button>`;}
function labelHelp(label){const term=({'Number of clusters (K)':'K','Random seed':'Random seed','t-SNE seed':'Random seed','Perplexity':'Perplexity','Iterations':'Iterations','Learning rate':'Learning rate','Initializations':'Initializations','Visualization':'PCA','Plot dimensions':'3D view'})[label];return term?' '+help(term):'';}
function controls3(){return S.dimensions===3?`<div class="camera-controls"><label>Rotate horizontally<input id="yaw" type="range" min="-180" max="180" value="${S.camera?.yaw??35}"></label><label>Tilt vertically<input id="pitch" type="range" min="-85" max="85" value="${S.camera?.pitch??20}"></label><label>Zoom<input id="zoom" type="range" min="0.5" max="1.4" step="0.05" value="${S.camera?.zoom??1}"></label>${button('reset-view','Reset view')}</div><p class="fine">Drag to rotate, or focus the plot and use arrow keys. X/Y/Z labels identify the axes. Camera motion does not change groups.</p>`:'';}

function inspector(a){const names=a.indices.map(i=>a.display<0?`Row ${i+1}`:String(a.data.rows[i][a.display]));const matches=names.map((name,i)=>({name,i})).filter(r=>r.name.toLowerCase().includes(searchText.toLowerCase()));return `<details class="inspector" open><summary>Inspect examples and features</summary><p>Each point is one example; features are its measurements. Click a point in 3D, or search and choose an example below. In 3D, rings mark its five nearest neighbors using all fitted features—not screen position.</p><label class="field"><span>Search example names</span><input id="point-search" type="search" value="${esc(searchText)}"></label><div id="point-options">${pointOptions(matches)}</div><div id="point-detail" aria-live="polite">${pointDetail(a,names)}</div></details>`;}
function pointOptions(matches){return `<label class="field"><span>Choose an example (${matches.length} matches)</span><select id="point-choice"><option value="">Choose an example</option>${matches.map(r=>`<option value="${r.i}" ${selectedPoint===r.i?'selected':''}>${esc(r.name)} · row ${S.active.indices[r.i]+1}</option>`).join('')}</select></label>`;}
function pointDetail(a,names){if(selectedPoint==null)return '<p class="fine">Choose an example to see its values and nearest neighbors.</p>';const i=selectedPoint;return `<h3>${esc(names[i])} · Cluster ${a.model.labels[i]+1}</h3><p>Source row ${a.indices[i]+1}${a.names[a.model.labels[i]]?' · '+esc(a.names[a.model.labels[i]]):''}</p>${table(['Feature','Value','Unit'],a.prep.names.map((n,j)=>[n,fmt(a.raw[i][j]),units(a.prep.features[j],a.data)]))}<h3>Five nearest neighbors</h3><p class="fine">Euclidean distance in the fitted feature space. Smaller means more similar under your feature choices; it is not confidence.</p>${table(['Example','Cluster','Distance'],neighbors(a).map(r=>[names[r.i],a.model.labels[r.i]+1,fmt(Math.sqrt(r.d))]))}${button('clear-point','Clear selection')}`;}
function bindInspector(){const full=document.querySelector('.explorer-view.expanded');if(full)full.onkeydown=e=>{if(e.key==='Escape'){expanded=false;render();$('expand-view')?.focus();}if(e.key==='Tab'){const targets=[...full.querySelectorAll('button,input,select,summary,[tabindex="0"]')];const first=targets[0],last=targets.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};const choose=i=>{selectedPoint=i;persist();render();$('point-choice')?.focus();};const bindChoice=()=>{$('point-choice')?.addEventListener('change',e=>choose(e.target.value===''?null:+e.target.value));};bindChoice();if($('point-search'))$('point-search').oninput=e=>{searchText=e.target.value;const a=S.active;const matches=a.indices.map((ri,i)=>({name:a.display<0?`Row ${ri+1}`:String(a.data.rows[ri][a.display]),i})).filter(r=>r.name.toLowerCase().includes(searchText.toLowerCase()));$('point-options').innerHTML=pointOptions(matches);bindChoice();};act('clear-point',()=>choose(null));act('expand-view',()=>{expanded=!expanded;render();$('expand-view')?.focus();});}
function clusterDetails(a,editable=false){return `<div class="clusters">${a.model.centers.map((c,g)=>{let indices=a.model.labels.map((l,i)=>l===g?i:-1).filter(i=>i>=0);return `<div class="cluster" style="--cluster:${colors[g]}"><strong>Cluster ${g+1} · ${indices.length} examples</strong>${editable?`<label class="field"><span>Interpretive name</span><input data-cluster="${g}" maxlength="80" value="${esc(a.names[g]||'')}" placeholder="Name after investigating"></label>`:`<h3>${esc(a.names[g]||'Unnamed group')}</h3>`}<ul>${a.prep.names.map((n,j)=>`<li>${esc(n)} mean: ${fmt(C.mean(indices.map(i=>a.raw[i][j])))}</li>`).join('')}</ul><p class="fine">Examples: ${esc(indices.slice(0,4).map(i=>(a.display<0?`Row ${a.indices[i]+1}`:a.data.rows[a.indices[i]][a.display])).join(', '))}</p>${editable?field(`cluster-${g}`,'What do these examples have in common?','Cite feature values and an example.',a.notes[`cluster-${g}`]||''): `<p class="fine">${esc(a.notes[`cluster-${g}`]||'No interpretation written.')}</p>`}</div>`;}).join('')}</div>`;}
function results(a){return `<div class="layout"><section class="panel"><div class="sectionbar"><h2>Patterns in ${esc(a.data.name)}</h2><span class="badge">${a.model.centers.length} clusters · ${a.X.length} examples</span></div><div class="toolbar">${select('view','Visualization',[['features','Feature plot'],['pca','PCA'],['tsne','t-SNE']],S.view)}${select('dimensions','Plot dimensions',[[2,'2D'],[3,'3D']],S.dimensions||2)}${S.view==='features'?[...S.axes,...(S.dimensions===3?[S.axisZ??2]:[])].map((v,i)=>select(`axis${i}`,['X feature','Y feature','Z feature'][i],a.prep.names.map((n,j)=>[j,n]),Math.min(v,a.prep.names.length-1))).join(''):''}</div>${S.view==='tsne'?`<div class="toolbar">${num('perplexity','Perplexity',S.tsne.perplexity,1,a.X.length-1)}${num('iterations','Iterations',S.tsne.iterations,250,1500)}${num('learningRate','Learning rate',S.tsne.learningRate,1,1000)}${num('tsneSeed','t-SNE seed',S.tsne.seed,0,2147483647)}</div><div class="toolbar">${button('tsne','Compute t-SNE',false,busy)}${busy?button('cancel','Cancel t-SNE'):''}</div>${busy?'<p id="tsne-progress" role="status">Preparing t-SNE…</p>':''}`:''}<div ${expanded?'role="dialog" aria-modal="true" aria-label="Expanded visualization"':''} class="explorer-view ${expanded?'expanded':''}"><div class="toolbar">${button('expand-view',expanded?'Exit expanded view':'Expand visualization')}</div><div id="model-plot">${modelPlot(a)}</div>${controls3()}${inspector(a)}</div><p class="fine">About this view: ${help(S.view==='tsne'?'t-SNE':S.view==='pca'?'PCA':'Feature')}${S.view==='pca'?help('Explained variance'):''}</p><div class="legend">${a.model.centers.map((_,i)=>`<span><span class="dot" style="background:${colors[i]}"></span>${i+1} · ${esc(a.names[i]||`Cluster ${i+1}`)}</span>`).join('')}</div><div class="callout">${S.view==='pca'?'PCA combines features into axes that retain as much variation as possible. Overlap here can hide differences in other dimensions.':S.view==='tsne'?'t-SNE emphasizes local similarities. Axes have no original units; island size and spacing do not prove natural categories. Centers and new examples are not projected here.':'This chart shows the selected display features. All selected features were used to learn the groups.'} Changing the view does not change cluster assignments.</div>${(S.dimensions===3?a.embedding3:a.embedding)&&S.view==='tsne'?`<p class="fine">Completed embedding settings: ${esc(JSON.stringify((S.dimensions===3?a.embedding3:a.embedding).settings))}. Recompute to apply changed settings.</p>`:''}<details><summary>Accessible results table — all examples</summary>${table([...a.data.headers,'Cluster'],a.indices.map((ri,i)=>[...a.data.rows[ri],a.model.labels[i]+1]))}</details>${clusterDetails(a,true)}</section><aside class="panel side"><span class="eyebrow">04 / INVESTIGATE</span><h2>Explain the groups</h2><p class="hint">Names are your interpretation, not labels used for training.</p>${field('viewReflection','What does this view help you notice, and what can it not prove?','Support your answer with an example.',a.notes.viewReflection||'')}${field('limitation','What is one limitation supported by your results?','Consider overlap, outliers, feature choices, or representation.',a.notes.limitation||'')}<details><summary>Cluster quality and limitations</summary><p><strong>Inertia: ${fmt(a.model.inertia)}</strong> ${help('Inertia')}<br>Sum of squared distances to assigned centers. Compare only when data and preprocessing match. More clusters usually reduce it.</p><p><strong>Silhouette: ${fmt(a.model.silhouette)}</strong> ${help('Silhouette')}<br>Range −1 to 1. Higher values suggest greater separation relative to spread. Singleton examples score zero. Undefined for fewer than two groups or one group per example.</p><p>Neither metric proves usefulness, fairness, or natural categories. K-means struggles with curved groups, unequal density, and outliers.</p></details>${button('save-run','Save this run',true)}<p class="fine">Saves an unchanged snapshot of settings, results, names, and current explanations.</p></aside></div>`;}
function comparePage(){let runs=S.runs;return `<section class="panel"><h2>Compare saved runs</h2><p class="hint">Change one choice at a time. Compare members and feature profiles, not cluster numbers or colors.</p>${runs.length<2?'<div class="callout">Save at least two runs from Cluster results. Return to Features or Train to change one setting, fit again, and save the new result.</div>':''}<div class="compare">${[0,1].map((_,side)=>{let i=Math.min(S.comparison[side],runs.length-1),r=runs[i];return `<div>${select(`compare${side}`,side?'Comparison run':'Baseline run',runs.map((a,j)=>[j,`Run ${j+1} · K=${a.model.centers.length} · ${a.prep.names.join(', ')}`]),i)}${r?`<p><strong>${esc(r.data.name)}</strong></p><p class="fine">${esc(r.prep.names.join(', '))}<br>Scaling: ${r.prep.scale?'on':'off'} · Missing: ${r.prep.missing}<br>Seed ${r.settings.seed} · ${r.settings.restarts} initializations<br>Inertia ${fmt(r.model.inertia)} · Silhouette ${fmt(r.model.silhouette)}</p><p class="fine">Prediction: ${esc(r.notes.prediction||'Not recorded')}</p>${clusterDetails(r)}<details><summary>All member records</summary>${table(['Example','Cluster'],r.indices.map((ri,j)=>[(r.display<0?`Row ${ri+1}`:r.data.rows[ri][r.display]),r.model.labels[j]+1]))}</details>`:'<p>No saved run yet.</p>'}</div>`;}).join('')}</div>${field('comparison','What changed, and was that useful for your purpose?','Refer to the run numbers, specific examples, and settings.')}<p class="fine">Inertia is not directly comparable across different features, scaling, or datasets. Neither score identifies a universally best K.</p></section>`;}
function tryPage(a){return `<div class="layout"><section class="panel"><h2>Try an example the model has not seen</h2><p class="hint">Use the same measurements and units as your dataset. This assigns the example without changing the learned model.</p><form id="predict-form"><div class="clusters">${a.prep.names.map((n,j)=>`<label class="field"><span>${esc(n)} (${esc(units(a.prep.features[j],a.data))})</span><input name="feature${j}" type="number" step="any" ${a.prep.missing==='drop'?'required':''} placeholder="${fmt(a.prep.means[j])}"></label>`).join('')}</div><button class="primary" type="submit">Assign new example</button></form><div id="prediction-result" role="status"></div>${a.examples.length?`<h3>Recorded investigations</h3>${table([...a.prep.names,'Cluster','Distance'],a.examples.map(e=>[...e.values,e.cluster+1,fmt(e.distance)]))}`:''}${a.examples.map((e,i)=>field(`example-${i}`,`Explain example ${i+1}: why this group, and is it a good fit?`,'Try one typical and one unusual or borderline example.',a.notes[`example-${i}`]||'')).join('')}</section><aside class="panel side"><h2>Nearest does not mean certain</h2><p>The model uses its saved preprocessing and assigns the example to the nearest learned center.</p><div class="callout">Distance is not a probability or a confidence percentage. Even an unusual example receives a nearest group.</div><p class="hint">Without a correct target label, this investigation does not establish classification accuracy.</p></aside></div>`;}
function explorePage(){if(!available())return `<section class="panel empty"><h2>${S.stale?'Your model needs refitting':'Train your first model'}</h2><p>Choose features and fit a model before exploring its results.</p>${button('go-train','Go to Train',true)}${S.runs.length?comparePage():''}</section>`;return `<div class="tabs" role="tablist" aria-label="Explore sections">${[['results','Cluster results'],['compare','Compare saved runs'],['try','Try a new example']].map(([v,t])=>`<button data-tab="${v}" role="tab" tabindex="${S.tab===v?0:-1}" aria-selected="${S.tab===v}">${t}</button>`).join('')}</div>${S.tab==='compare'?comparePage():S.tab==='try'?tryPage(S.active):results(S.active)}`;}
function checklist(){return [[!!S.notes.purpose,'Purpose recorded'],[!!S.notes.features,'Feature choices explained'],[S.runs.length>=2,'At least two runs saved'],[!!S.notes.comparison,'Comparison explained'],[(S.active?.examples.length||0)>=2,'Two new examples investigated'],[!!S.active?.notes.limitation,'A limitation supported by evidence'],[!!S.notes.individual,'Individual reflection recorded']];}
function cardPage(){return `<div class="layout"><section class="panel"><div class="sectionbar"><h2>Your model card ${help('Model card')} <span class="badge">Optional writing</span></h2><span class="badge">Student-written reasoning</span></div><p class="hint">A model card explains the purpose, data, settings, and limits of a model. You may keep reflections in a separate document. Exports still include your calculated results and saved run settings.</p>${field('title','Project title')}${field('authors','Authors / group')}${field('purpose','Project purpose')}${field('source','Data source and limitations')}${field('features','Feature justification')}${field('learned','What you chose and what the model learned')}${field('comparison','Comparison: what changed and why it matters')}${field('intended','Intended use','Who could use this grouping, and for what?')}${field('inappropriate','When should this model not be used?')}${field('peer','Peer feedback','Record a specific observation from your reviewer.')}${field('response','Your response to feedback','What did you change, or why did you retain your design?')}${field('individual','Individual reflection','What did you choose, what did the algorithm learn, and what evidence would make you reconsider your model?')}</section><aside class="panel side"><span class="eyebrow">05 / DOCUMENT</span><h2>Evidence, ready to share</h2><ul class="checklist">${checklist().map(([ok,t])=>`<li>${ok?'✓':'○'} ${t}</li>`).join('')}</ul><p class="fine">Writing can be completed in a separate document. This optional checklist is not a grade; exports work without completing these fields.</p><div class="toolbar">${button('report','Export project report',true)}${button('model-export','Export fitted model JSON',false,!available())}${button('cluster-export','Export clustered CSV',false,!available())}${button('model-open','Open fitted model JSON')}</div>${!available()?'<p class="fine">Fit a current model to enable model and clustered CSV exports.</p>':''}<div class="callout">Your report separates calculated results from your explanations. Prepare a short presentation or 1–2-minute demonstration using the evidence.</div><p class="fine">A fitted model JSON contains centers and preprocessing. A project download also includes data, runs, and writing.</p></aside></div>`;}
function makeActive(p,model,restarts=S.restarts){return{...C.clone(p),model,names:Array(model.centers.length).fill(''),notes:C.clone(S.notes),examples:[],data:C.clone(S.data),display:S.display,settings:{seed:S.seed,restarts,maxIter:S.maxIter,k:S.k},signature:signature(),created:new Date().toISOString()};}
function completeStep(){if(step?.done){const p=prepared(),m=C.finish(step);m.silhouette=C.silhouette(p.X,m.labels);S.active=makeActive(p,m,1);S.stale=false;clearInterval(timer);timer=null;persist();}}
function runWorker(type,X,settings){cancelWork();busy=true;worker=new Worker('./worker.js',{type:'module'});worker.onmessage=({data})=>{if(data.type==='progress'){if($('tsne-progress'))$('tsne-progress').textContent=`t-SNE iteration ${data.iteration} of ${settings.iterations}`;return;}if(data.type==='error'){cancelWork();notice(data.message);render();return;}if(type==='fit'){S.active=makeActive(prepared(),data.model);S.stale=false;step=null;notice('Model fitted. Explore the results and save your run.');}else{S.active[settings.dimensions===3?'embedding3':'embedding']={points:data.points,settings:C.clone(settings),implementation:'karpathy/tsnejs · SHA256 70a7d6cd823fdc707c91b7cfa0036cd59a2199de6d5b7af9bb1f1081325a77f1'};notice('t-SNE view complete. Cluster assignments are unchanged.');}cancelWork();persist();render();};worker.onerror=e=>{cancelWork();notice('Calculation could not run: '+e.message);render();};worker.postMessage({type,X,k:S.k,settings});render();}
function act(id,fn){$(id)?.addEventListener('click',()=>{try{fn();}catch(e){notice(e.message);}});}
function change(id,fn){$(id)?.addEventListener('change',e=>{try{fn(e.target);persist();render();}catch(err){notice(err.message);}});}
async function importCSV(f){if(f.size>2*1024*1024)throw Error('CSV files must be 2 MB or smaller.');if(!/\.csv$/i.test(f.name))throw Error('Choose a CSV file.');if(!confirm('Replace the current dataset? Saved runs will be kept.'))return;let data=C.parseCSV(await f.text());S.data={...data,name:f.name,source:'Student-uploaded CSV',description:'Inspect columns, units, missing values, and whether this data represents your intended use.',units:data.headers.map(()=> 'units not supplied')};S.display=C.describe(S.data).findIndex(d=>!d.numeric||d.reserved);S.features=C.describe(S.data).map((d,i)=>d.numeric&&!d.constant&&!d.reserved&&i!==S.display?i:-1).filter(i=>i>=0);invalidate();render();notice(`Loaded ${S.data.name} — ${S.data.rows.length} examples, ${S.features.length} usable numerical features. This is now your active dataset. Continue to Features.`, 'success');document.querySelector('.data-preview')?.focus();}
function focusStage(){$('main').focus();$('main').scrollIntoView?.({block:'start'});}
function bind(){
 bindHelp();bind3();bindInspector();
 document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{cancelWork();S.stage=+b.dataset.stage;persist();render();focusStage();});
 document.querySelectorAll('[data-note]').forEach(t=>t.oninput=()=>{let key=t.dataset.note;if(S.stage===3&&S.tab!=='compare'&&S.active){S.active.notes[key]=t.value;}else{S.notes[key]=t.value;if(S.active&&key==='learned'&&!S.stale)S.active.notes[key]=t.value;}saveSoon();});
 document.querySelectorAll('[data-feature]').forEach(t=>t.onchange=()=>{let i=+t.dataset.feature;S.features=t.checked?[...S.features,i].sort((a,b)=>a-b):S.features.filter(f=>f!==i);invalidate();render();});
 document.querySelectorAll('[data-cluster]').forEach(t=>t.oninput=()=>{S.active.names[+t.dataset.cluster]=t.value;saveSoon();});
 document.querySelectorAll('[data-tab]').forEach(t=>{t.onclick=()=>{cancelWork();S.tab=t.dataset.tab;persist();render();};t.onkeydown=e=>{const keys=['ArrowLeft','ArrowRight','Home','End'];if(!keys.includes(e.key))return;e.preventDefault();let tabs=['results','compare','try'],i=tabs.indexOf(S.tab);S.tab=tabs[e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3];cancelWork();persist();render();document.querySelector(`[data-tab="${S.tab}"]`).focus();};});
 act('next',()=>{if(S.stage===1)prepared();if(S.stage===2&&!available())throw Error('Train your model before continuing to Explore.');S.stage++;persist();render();focusStage();});act('back',()=>{cancelWork();S.stage--;persist();render();focusStage();});act('go-train',()=>{S.stage=2;render();focusStage();});
 act('load-sample',()=>{if(!confirm('Replace the current dataset? Saved runs and project writing will be kept.'))return;S.data=sample($('sample').value);S.features=S.data.headers.map((_,i)=>i).slice(1);S.display=0;invalidate();render();});act('upload-csv',()=>pick('.csv',importCSV));
 change('display',t=>{S.display=+t.value;S.features=S.features.filter(f=>f!==S.display);invalidate();});act('sample-csv',()=>download('dataset.csv',C.csv([S.data.headers,...S.data.rows]),'text/csv'));
 change('scale',t=>{S.scale=t.checked;invalidate();});change('missing',t=>{S.missing=t.value;invalidate();});for(const key of ['k','seed','restarts','maxIter'])change(key,t=>{let n=+t.value;if(!Number.isInteger(n)||n<+t.min||n>+t.max)throw Error(`Enter a whole number from ${t.min} to ${t.max}.`);S[key]=n;invalidate();});
 act('fit',()=>{let p=prepared();C.createStepper(p.X,S.k,S.seed,null,S.maxIter);runWorker('fit',p.X,{seed:S.seed,restarts:S.restarts,maxIter:S.maxIter});});
 act('watch',()=>{cancelWork();step=C.createStepper(prepared().X,S.k,S.seed,null,S.maxIter);render();});act('step',()=>{C.advance(step);completeStep();render();});act('play',()=>{if(timer){clearInterval(timer);timer=null;render();return;}timer=setInterval(()=>{C.advance(step);completeStep();render();},650);render();});act('reset',()=>{cancelWork();step=C.createStepper(prepared().X,S.k,S.seed,null,S.maxIter);render();});act('cancel',()=>{cancelWork();notice('Calculation cancelled. Previous completed results were preserved.');render();});
 change('view',t=>{cancelWork();S.view=t.value;});change('dimensions',t=>{cancelWork();S.dimensions=+t.value;});change('axis2',t=>S.axisZ=+t.value);for(let i=0;i<2;i++)change(`axis${i}`,t=>S.axes[i]=+t.value);
 for(const key of ['perplexity','iterations','learningRate'])change(key,t=>S.tsne[key]=+t.value);change('tsneSeed',t=>S.tsne.seed=+t.value);act('tsne',()=>{C.tsneSettings(S.active.X.length,S.tsne);runWorker('tsne',S.active.X,{...S.tsne,dimensions:S.dimensions||2});});
 act('save-run',()=>{if(!available())throw Error('Train a current model first.');if(S.runs.length>=20)throw Error('This project supports 20 saved runs. Download your project before starting another.');S.runs.push(C.clone(S.active));persist();notice(`Run ${S.runs.length} saved as an unchanged snapshot. Continue investigating or compare runs.`);});for(let i=0;i<2;i++)change(`compare${i}`,t=>S.comparison[i]=+t.value);
 $('predict-form')?.addEventListener('submit',e=>{e.preventDefault();try{let a=S.active,v=a.prep.names.map((_,j)=>e.target.elements[`feature${j}`].value),x=C.transform(v,a.prep),g=C.nearest(x,a.model.centers),distance=Math.sqrt(C.d2(x,a.model.centers[g]));a.examples.push({values:v,cluster:g,distance});persist();render();$('prediction-result').innerHTML=`<div class="callout">Assigned to Cluster ${g+1}${a.names[g]?' · '+esc(a.names[g]):''}. Distance: ${fmt(distance)} in fitted feature space. This is not a confidence score.</div>`;}catch(err){notice(err.message);}});
 act('report',()=>{download('cluster-lab-report.html',report(),'text/html');notice('Report exported. Open it in a browser to read or print to PDF.');});act('model-export',()=>download('cluster-lab-model.json',JSON.stringify(modelExport(S.active),null,2)));act('cluster-export',()=>{let a=S.active;download('clustered-data.csv',C.csv([[...a.data.headers,'Cluster','Cluster name'],...a.indices.map((ri,i)=>[...a.data.rows[ri],a.model.labels[i]+1,a.names[a.model.labels[i]]||''])]),'text/csv');});act('model-open',()=>pick('.json',async f=>{let m=C.validateModel(JSON.parse(await f.text()));openModel(m);}));
}
function bindHelp(){document.querySelectorAll('[data-help]').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();let d=$('definition-dialog');if(!d){d=document.createElement('dialog');d.id='definition-dialog';d.setAttribute('aria-labelledby','definition-title');d.innerHTML='<h2 id="definition-title"></h2><p id="definition-text"></p><button id="definition-close">Close</button>';document.body.append(d);}d.returnFocus=b;$('definition-title').textContent=b.dataset.help;$('definition-text').textContent=definitions[b.dataset.help]||'';const close=()=>{if(d.close)d.close();else d.removeAttribute('open');d.returnFocus?.focus();};$('definition-close').onclick=close;d.oncancel=e=>{e.preventDefault();close();};d.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();close();}if(e.key==='Tab'){e.preventDefault();$('definition-close').focus();}};d.onclick=e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}};if(d.showModal)d.showModal();else d.setAttribute('open','');$('definition-close').focus();});}
function bind3(){const redraw=()=>{if($('model-plot')&&S.active){$('model-plot').innerHTML=modelPlot(S.active);applyClusterFilter($('main'),S.active);bindDrag();}saveSoon();};for(const k of ['yaw','pitch','zoom']){const input=$(k);if(input)input.oninput=()=>{S.camera=S.camera||{yaw:35,pitch:20,zoom:1};S.camera[k]=+input.value;redraw();};}act('reset-view',()=>{S.camera={yaw:35,pitch:20,zoom:1};persist();render();});bindDrag();function bindDrag(){const svg=$('plot3d');if(!svg)return;let last=null,start=null,point=null,moved=false;svg.onpointerdown=e=>{start=[e.clientX,e.clientY];point=e.target?.closest?.("[data-point]")?.dataset.point;moved=false;last=[e.clientX,e.clientY];svg.setPointerCapture?.(e.pointerId);};svg.onpointermove=e=>{if(!last)return;if(Math.hypot(e.clientX-start[0],e.clientY-start[1])>4)moved=true;const dx=e.clientX-last[0],dy=e.clientY-last[1];last=[e.clientX,e.clientY];adjust(dx*.5,dy*.5,false);};svg.onpointerup=()=>{last=null;if(!moved&&point!=null){selectedPoint=+point;render();$('point-choice')?.focus();}else redraw();};svg.onpointercancel=()=>{last=null;redraw();};svg.onkeydown=e=>{const deltas={ArrowLeft:[-5,0],ArrowRight:[5,0],ArrowUp:[0,-5],ArrowDown:[0,5]};if(!deltas[e.key])return;e.preventDefault();adjust(...deltas[e.key]);$('plot3d')?.focus();};function adjust(dx,dy,replace=true){let c=S.camera||{yaw:35,pitch:20,zoom:1};c.yaw=((c.yaw+dx+540)%360)-180;c.pitch=Math.max(-85,Math.min(85,c.pitch+dy));S.camera=c;if($('yaw'))$('yaw').value=c.yaw;if($('pitch'))$('pitch').value=c.pitch;if(replace)redraw();else{const wrapper=document.createElement('div');wrapper.innerHTML=modelPlot(S.active);svg.innerHTML=wrapper.querySelector('svg').innerHTML;applyClusterFilter($('main'),S.active);saveSoon();}}}}
function modelExport(a){return {schema:1,kind:'cluster-lab-model',prep:a.prep,centers:a.model.centers,names:a.names,settings:a.settings};}
function download(name,text,type='application/json'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function pick(accept,fn){const input=$('file');input.value='';input.accept=accept;input.onchange=async()=>{try{let f=input.files[0];if(!f)return;if(f.size>15*1024*1024)throw Error('File limit: 15 MB.');await fn(f);}catch(e){notice(e.message);}};input.click();}
function validateProject(p){if(p?.schema!==1||p.kind!=='cluster-lab-project'||!p.data||!Array.isArray(p.runs)||p.runs.length>20||!p.notes||typeof p.notes!=='object')throw Error('Not a valid Pattern Lab v1 project.');if(!Array.isArray(p.data.headers)||!Array.isArray(p.data.rows))throw Error('Missing dataset.');C.parseCSV(C.csv([p.data.headers,...p.data.rows]));if(![p.k,p.seed,p.restarts,p.maxIter].every(Number.isInteger)||p.k<1||p.k>12||p.restarts<1||p.restarts>20||p.maxIter<1||p.maxIter>1000||typeof p.scale!=='boolean'||!['drop','mean'].includes(p.missing)||!['features','pca','tsne'].includes(p.view)||!['results','compare','try'].includes(p.tab)||!Array.isArray(p.axes)||p.axes.length!==2||p.axes.some(x=>!Number.isInteger(x)||x<0||x>24)||!p.tsne||!Object.values(p.tsne).every(Number.isFinite)||!Array.isArray(p.comparison)||p.comparison.length!==2||p.comparison.some(x=>!Number.isInteger(x)||x<0)||Object.values(p.notes).some(x=>typeof x!=='string'))throw Error('Invalid project controls or writing.');if(!Number.isInteger(p.stage)||p.stage<0||p.stage>4||!Array.isArray(p.features)||p.features.some(i=>!Number.isInteger(i)||i<0||i>=p.data.headers.length)||!Number.isInteger(p.display)||p.display< -1||p.display>=p.data.headers.length)throw Error('Invalid project settings.');for(let r of [...p.runs,...(p.active?[p.active]:[])]){C.validateModel(modelExport(r));delete r.pca;delete r.pca2;delete r.pca3;if(!Number.isInteger(r.model.iterations)||r.model.iterations<0||!Number.isFinite(r.model.inertia)||!(r.model.silhouette===null||Number.isFinite(r.model.silhouette))||typeof r.model.converged!=='boolean'||!r.settings||!Object.values(r.settings).every(Number.isFinite))throw Error('Invalid saved model statistics.');C.matrix(r.X);C.matrix(r.raw);if(r.X.length>500||r.X.length!==r.raw.length||r.model.labels.length!==r.X.length||r.model.labels.some(l=>!Number.isInteger(l)||l<0||l>=r.model.centers.length)||!Array.isArray(r.indices)||r.indices.length!==r.X.length||r.indices.some(i=>!Number.isInteger(i)||i<0||i>=r.data.rows.length)||!r.notes||!Array.isArray(r.examples)||!Array.isArray(r.names)||r.names.length!==r.model.centers.length)throw Error('Invalid saved run.');if(r.names.some(n=>typeof n!=='string')||Object.values(r.notes).some(n=>typeof n!=='string')||r.examples.some(e=>!Array.isArray(e.values)||e.values.length!==r.prep.names.length||!Number.isInteger(e.cluster)||e.cluster<0||e.cluster>=r.model.centers.length||!Number.isFinite(e.distance)))throw Error('Invalid run evidence.');for(const [key,dim] of [['embedding',2],['embedding3',3]])if(r[key]&&(r[key].points.length!==r.X.length||r[key].points.some(row=>row.length!==dim||row.some(v=>!Number.isFinite(v)))))throw Error('Invalid embedding.');}p.dimensions=p.dimensions??2;p.axisZ=p.axisZ??2;p.camera=p.camera??{yaw:35,pitch:20,zoom:1};if(![2,3].includes(p.dimensions)||!Number.isInteger(p.axisZ)||p.axisZ<0||p.axisZ>24||!p.camera||!['yaw','pitch','zoom'].every(k=>Number.isFinite(p.camera[k]))||Math.abs(p.camera.yaw)>180||Math.abs(p.camera.pitch)>85||p.camera.zoom<.5||p.camera.zoom>1.4)throw Error('Invalid 3D camera.');return p;}
function openModel(m){$('main').innerHTML=`<div class="eyebrow">RELOADED MODEL</div><h1>Use your fitted model.</h1><p class="intro">Saved centers and preprocessing loaded. This view does not refit the model or replace your project.</p><section class="panel"><h2>Assign a new example</h2><form id="loaded-predict">${m.prep.names.map((n,i)=>`<label class="field"><span>${esc(n)}</span><input type="number" step="any" name="v${i}" ${m.prep.missing==='drop'?'required':''}></label>`).join('')}<button class="primary">Assign new example</button></form><p id="loaded-result" role="status"></p>${button('return','Return to project')}</section>`;act('return',render);$('loaded-predict').onsubmit=e=>{e.preventDefault();try{let x=C.transform(m.prep.names.map((_,i)=>e.target.elements[`v${i}`].value),m.prep),g=C.nearest(x,m.centers);$('loaded-result').textContent=`Cluster ${g+1} · ${m.names?.[g]||'Unnamed'} · Distance ${fmt(Math.sqrt(C.d2(x,m.centers[g])))}. Distance is not confidence.`;}catch(err){notice(err.message);}};}
function report(){let runs=[...S.runs];if(S.active)runs.push(S.active);return `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pattern Lab project report</title><style>body{font:16px/1.6 system-ui;color:#20352e;max-width:1000px;margin:35px auto;padding:20px}h1,h2,h3{line-height:1.2}section{border-top:1px solid #bbb;margin-top:25px;padding-top:15px}table{border-collapse:collapse;font-size:12px;width:100%}td,th{border:1px solid #ddd;padding:6px;text-align:left}p{white-space:pre-wrap}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}.clusters{display:grid;grid-template-columns:1fr 1fr;gap:15px}.cluster{border:1px solid #ddd;padding:12px}.plot{width:100%;max-height:360px}.fine{font-size:13px}.tablewrap{overflow:auto}@media print{button{display:none}section{break-inside:avoid}body{margin:0;padding:0}.tablewrap{overflow:visible}}</style><body><h1>${esc(S.notes.title||'Pattern Lab project report')}</h1><p>Exported ${esc(new Date().toISOString())} · ${S.stale?'Active model outdated; use saved runs as evidence.':'Current workspace snapshot.'}</p><h2>Student-written reasoning</h2>${Object.entries(S.notes).map(([k,v])=>`<h3>${esc(k)}</h3><p>${esc(v||'Not recorded')}</p>`).join('')}<h2>Calculated results and run-specific evidence</h2>${runs.map((a,i)=>`<section><h2>${i<S.runs.length?`Saved run ${i+1}`:'Active model (not necessarily saved)'}</h2><p>Dataset: ${esc(a.data.name)} · Source: ${esc(a.data.source)}<br>Features: ${esc(a.prep.names.join(', '))}<br>K: ${a.model.centers.length}; scaling: ${a.prep.scale}; missing: ${a.prep.missing}; seed: ${a.settings.seed}; initializations: ${a.settings.restarts}<br>Status: ${a.model.converged?'converged':'not converged'}; updates: ${a.model.iterations}; inertia: ${fmt(a.model.inertia)}; silhouette: ${fmt(a.model.silhouette)}</p>${plot(a.raw.map(r=>r.slice(0,2)),a.model.labels,[],a.prep.names.slice(0,2))}${clusterDetails(a)}<h3>Student explanations for this run</h3>${Object.entries(a.notes).map(([k,v])=>`<p><strong>${esc(k)}</strong><br>${esc(v)}</p>`).join('')}<h3>New examples</h3>${table([...a.prep.names,'Cluster','Distance'],a.examples.map(e=>[...e.values,e.cluster+1,fmt(e.distance)]))}<details open><summary>Member records</summary>${table([...a.data.headers,'Cluster'],a.indices.map((ri,j)=>[...a.data.rows[ri],a.model.labels[j]+1]))}</details>${a.embedding3?`<h3>Saved 3D t-SNE (fixed camera projection)</h3>${draw3(a.embedding3.points,a.model.labels,[],['t-SNE 1','t-SNE 2','t-SNE 3'],a.indices.map(i=>'Row '+(i+1)),{yaw:35,pitch:20,zoom:1},colors,esc,fmt)}<p>Settings: ${esc(JSON.stringify(a.embedding3.settings))}. View rotation is available in the project; this report is static.</p>`:''}${a.embedding?`<h3>Saved t-SNE view</h3>${plot(a.embedding.points,a.model.labels,[],['t-SNE 1','t-SNE 2'])}<p>Settings: ${esc(JSON.stringify(a.embedding.settings))}. Axes have no original units; separation does not establish categories.</p>`:''}<h3>Reproducibility details</h3><pre>${esc(JSON.stringify({settings:a.settings,preprocessing:a.prep,centers:a.model.centers},null,2))}</pre></section>`).join('')}<section><h2>Interpretation limits</h2><p>Silhouette is not accuracy. Inertia comparisons require the same dataset and feature transformation. Cluster numbers are arbitrary across runs. Neither metric proves usefulness or fairness.</p></section></body></html>`;}
try{const stored=localStorage.getItem('cluster-lab-v1');if(stored)S=validateProject(JSON.parse(stored));status('Saved in this browser');}catch(e){notice('A saved workspace could not be loaded. The default sample is available; open a downloaded project to recover your work.');}
$('download-project').onclick=()=>{persist();download('cluster-lab-project.json',JSON.stringify(S,null,2));};$('open-project').onclick=()=>pick('.json',async f=>{let p=validateProject(JSON.parse(await f.text()));if(!confirm('Open this project and replace the current workspace? Download your current project first if needed.'))return;cancelWork();S=p;step=null;persist();render();notice('Project restored with saved runs and writing.');});
render();
export {render,report,validateProject,modelExport,makeActive};
